import 'package:flutter/foundation.dart';

/// Purpose selection is a native setup input, not permission to send a prompt,
/// assign a saved connection, test a provider or transfer an existing credential.
enum SupportProviderPurpose { roleplay, studio, memoryBooks, astoria }

enum SupportProviderActionKind { create, update, undo }

enum SupportProviderDestinationKind { standard, customHttps, customInsecure }

enum SupportProviderVerification { notTested, modelsListed, generationVerified }

/// Keyless form input. IDs are generated by the native review owner, never
/// accepted from a tool/card. No secret, credential handle or approval belongs
/// in this value or its serialization. Constructing it grants no authority.
@immutable
final class SupportProviderSetupInput {
  const SupportProviderSetupInput({
    required this.purpose,
    required this.name,
    required this.protocol,
    required this.endpoint,
    required this.model,
    required this.maxTokens,
    required this.contextSize,
    required this.temperature,
  });

  final SupportProviderPurpose purpose;
  final String name, protocol, endpoint, model;
  final int maxTokens, contextSize;
  final double temperature;

  @override
  String toString() => 'SupportProviderSetupInput';
}

/// Bounded, current-policy display only. The native service must validate and
/// reproject all variable fields on every render. This snapshot is not a row
/// observation, mutation precondition, credential route or restored Undo receipt.
@immutable
final class SupportProviderSetupValue {
  const SupportProviderSetupValue({
    required this.connectionId,
    required this.name,
    required this.protocol,
    required this.endpoint,
    required this.model,
    required this.maxTokens,
    required this.contextSize,
    required this.temperature,
  });

  final String connectionId, name, protocol, endpoint, model;
  final int maxTokens, contextSize;
  final double temperature;

  @override
  String toString() => 'SupportProviderSetupValue';
}

@immutable
final class SupportProviderSetupPreview {
  const SupportProviderSetupPreview({
    required this.kind,
    required this.purpose,
    required this.destinationKind,
    required this.before,
    required this.after,
  });

  final SupportProviderActionKind kind;
  final SupportProviderPurpose purpose;
  final SupportProviderDestinationKind destinationKind;
  final SupportProviderSetupValue? before, after;
}

/// Saving configuration/key and observing a provider are separate facts. A
/// configured flag/count never implies reachability, model availability, valid
/// authentication, authorization to generate, or a still-current test result.
@immutable
final class SupportProviderReadiness {
  const SupportProviderReadiness({
    required this.configurationSaved,
    required this.credentialConfigured,
    required this.characterCount,
    this.verification = SupportProviderVerification.notTested,
  });

  final bool configurationSaved, credentialConfigured;
  final int characterCount;
  final SupportProviderVerification verification;
}
